import pymupdf,re
d=pymupdf.open('realplan.pdf')
for pg in [31,33,35]:
  p=d[pg]
  hexes=[]
  for g in p.get_drawings():
    its=g['items']; r=g['rect']
    if all(i[0]=='l' for i in its) and len(its)==6 and 27.5<r.width<29 and 24<r.height<25.2:
        if not any(abs(r.x0-u.x0)<2 and abs(r.y0-u.y0)<2 for u in hexes): hexes.append(r)
  ws=p.get_text('words')
  print('page',pg,'hexes',len(hexes))
  for r in hexes:
    ins=sorted([w for w in ws if r.x0-1<(w[0]+w[2])/2<r.x1+1 and r.y0-1<(w[1]+w[3])/2<r.y1+1],key=lambda w:w[1])
    print('  ',round(r.x0),round(r.y0),[w[4] for w in ins])
